const nw = msg.data.new_state;
const ow = msg.data.old_state;

if (!nw || !nw.attributes || !nw.attributes.lista_przedmiotow) return null;

const entityId = nw.entity_id;
const nowePrzedmioty = nw.attributes.lista_przedmiotow;

// Tworzymy unikalny klucz cache dla konkretnej encji (p1 lub p2)
const cacheKey = 'oceny_cache_' + entityId.replace(/\./g, '_');

// Pobieramy dane z cache lub ze stanu poprzedniego
let starePrzedmioty = context.get(cacheKey) || (ow ? ow.attributes.lista_przedmiotow : []);

// Zapisujemy nowe dane do cache dla tej konkretnej encji
context.set(cacheKey, nowePrzedmioty);

// Funkcja pomocnicza do tworzenia unikalnego klucza oceny
const getGradeKey = (przedmiot, o) => `${przedmiot}|${o.w}|${o.d}|${o.i}`;

const znaneKlucze = new Set();
starePrzedmioty.forEach(p => {
    if (p.oceny) {
        p.oceny.forEach(o => znaneKlucze.add(getGradeKey(p.przedmiot, o)));
    }
});

// Wyciągamy imię i okres
const friendlyName = nw.attributes.friendly_name || "";
const imie = friendlyName.split(' (')[0].replace('Oceny: ', '');
const okres = friendlyName.includes('Okres 1') ? "z 1. semestru" : "z 2. semestru";

let wiadomosci = [];

nowePrzedmioty.forEach(p => {
    if (p.oceny) {
        p.oceny.forEach(o => {
            const klucz = getGradeKey(p.przedmiot, o);

            if (!znaneKlucze.has(klucz)) {
                wiadomosci.push({
                    payload: {
                        title: `Nowa ocena (${p.przedmiot})`,
                        message: `${imie} otrzymał(a) **${o.w}** z przedmiotu **${p.przedmiot}** (${okres}).\nOpis: ${o.i}`,
                        notification_id: "vultron_ocena_" + p.przedmiot.replace(/\s/g, '_')
                    }
                });
                znaneKlucze.add(klucz);
            }
        });
    }
});

if (wiadomosci.length > 0) return [wiadomosci];
return null;
